#!/usr/bin/env node
// node tools/zkverdict-vkey.mjs: writes zkverdict-vkey.json, the Groth16 verification key the browser checks proven
// Neuro verdicts with, parsed from the committed zetaphy-network/contracts/NeuroScoreVerifier.sol (read only: that file
// is generated by the zk ceremony tooling and never edited here). test/zkverdict.test.mjs checks the two agree.
//   node tools/zkverdict-vkey.mjs           write
//   node tools/zkverdict-vkey.mjs --check   only compare (exit 1 when they differ)
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { vkeyFromVerifierSol } from '../zkverdict-core.js';

const HUB = fileURLToPath(new URL('..', import.meta.url));
export const VERIFIER_SOL = fileURLToPath(new URL('../../zetaphy-network/contracts/NeuroScoreVerifier.sol', import.meta.url));
export const vkeyJson = () => JSON.stringify({ source: 'zetaphy-network/contracts/NeuroScoreVerifier.sol', ...vkeyFromVerifierSol(readFileSync(VERIFIER_SOL, 'utf8')) }, null, 1) + '\n';

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const text = vkeyJson();
  const file = `${HUB}zkverdict-vkey.json`;
  if (process.argv.includes('--check')) {
    const same = existsSync(file) && readFileSync(file, 'utf8') === text;
    console.log(same ? 'zkverdict-vkey.json matches NeuroScoreVerifier.sol' : 'zkverdict-vkey.json differs from NeuroScoreVerifier.sol');
    process.exit(same ? 0 : 1);
  }
  writeFileSync(file, text);
  console.log('zkverdict-vkey.json written');
}
